package git

import (
	"fmt"
	"os"
	"path/filepath"

	"forgejo.org/modules/setting"
	"forgejo.org/modules/util"
)

func getHookTemplates() (hookNames, hookTpls, giteaHookTpls []string) {
	hookNames = []string{"pre-receive", "update", "post-receive"}
	hookTpls = []string{
		// for pre-receive
		fmt.Sprintf(`#!/usr/bin/env %s
# AUTO GENERATED BY GITEA, DO NOT MODIFY
data=$(cat)
exitcodes=""
hookname=$(basename "$0")

for hook in "$(dirname "$0")/${hookname}.d"/*; do
  test -x "${hook}" && test -f "${hook}" || continue
  echo "${data}" | "${hook}"
  exitcodes="${exitcodes} $?"
done

# Custom hooks
custom_hooks_dir="./hooks/${hookname}.d"
if [ -d "${custom_hooks_dir}" ]; then
  for hook in "${custom_hooks_dir}"/*; do
    if [ "$(basename "${hook}")" != "gitea" ]; then
      test -x "${hook}" && test -f "${hook}" || continue
      echo "${data}" | "${hook}"
      exitcodes="${exitcodes} $?"
    fi
  done
fi

for i in ${exitcodes}; do
  [ "${i}" -eq 0 ] || exit "${i}"
done
`, setting.ScriptType),

		// for update
		fmt.Sprintf(`#!/usr/bin/env %s
# AUTO GENERATED BY GITEA, DO NOT MODIFY
exitcodes=""
hookname=$(basename "$0")

for hook in "$(dirname "$0")/${hookname}.d"/*; do
  test -x "${hook}" && test -f "${hook}" || continue
  "${hook}" "$1" "$2" "$3"
  exitcodes="${exitcodes} $?"
done

# Custom hooks
custom_hooks_dir="./hooks/${hookname}.d"
if [ -d "${custom_hooks_dir}" ]; then
  for hook in "${custom_hooks_dir}"/*; do
    if [ "$(basename "${hook}")" != "gitea" ]; then
      test -x "${hook}" && test -f "${hook}" || continue
      "${hook}" "$1" "$2" "$3"
      exitcodes="${exitcodes} $?"
    fi
  done
fi

for i in ${exitcodes}; do
  [ "${i}" -eq 0 ] || exit "${i}"
done
`, setting.ScriptType),

		// for post-receive
		fmt.Sprintf(`#!/usr/bin/env %s
# AUTO GENERATED BY GITEA, DO NOT MODIFY
data=$(cat)
exitcodes=""
hookname=$(basename "$0")

for hook in "$(dirname "$0")/${hookname}.d"/*; do
  test -x "${hook}" && test -f "${hook}" || continue
  echo "${data}" | "${hook}"
  exitcodes="${exitcodes} $?"
done

# Custom hooks
custom_hooks_dir="./hooks/${hookname}.d"
if [ -d "${custom_hooks_dir}" ]; then
  for hook in "${custom_hooks_dir}"/*; do
    if [ "$(basename "${hook}")" != "gitea" ]; then
      test -x "${hook}" && test -f "${hook}" || continue
      echo "${data}" | "${hook}"
      exitcodes="${exitcodes} $?"
    fi
  done
fi
for i in ${exitcodes}; do
  [ "${i}" -eq 0 ] || exit "${i}"
done
`, setting.ScriptType),
	}

	giteaHookTpls = []string{
		// for pre-receive
		fmt.Sprintf(`#!/usr/bin/env %s
# AUTO GENERATED BY GITEA, DO NOT MODIFY
%s hook --config=%s pre-receive
`, setting.ScriptType, util.ShellEscape(setting.AppPath), util.ShellEscape(setting.CustomConf)),

		// for update
		fmt.Sprintf(`#!/usr/bin/env %s
# AUTO GENERATED BY GITEA, DO NOT MODIFY
%s hook --config=%s update $1 $2 $3
`, setting.ScriptType, util.ShellEscape(setting.AppPath), util.ShellEscape(setting.CustomConf)),

		// for post-receive
		fmt.Sprintf(`#!/usr/bin/env %s
# AUTO GENERATED BY GITEA, DO NOT MODIFY
%s hook --config=%s post-receive
`, setting.ScriptType, util.ShellEscape(setting.AppPath), util.ShellEscape(setting.CustomConf)),
	}

	// although only new git (>=2.29) supports proc-receive, it's still good to create its hook, in case the user upgrades git
	hookNames = append(hookNames, "proc-receive")
	hookTpls = append(hookTpls,
		fmt.Sprintf(`#!/usr/bin/env %s
# AUTO GENERATED BY GITEA, DO NOT MODIFY
%s hook --config=%s proc-receive
`, setting.ScriptType, util.ShellEscape(setting.AppPath), util.ShellEscape(setting.CustomConf)))
	giteaHookTpls = append(giteaHookTpls, "")

	// reference-transaction (git >= 2.28) sees every ref update the git binary
	// makes, whatever the path: push, merge, API, AGit. The cluster's
	// replicator proposes the transaction in "prepared" and refuses it there
	// when the cluster does; "preparing" carries nothing it needs.
	//
	// The wrapper fails closed in "prepared": without the cluster's hook,
	// absent, empty or not executable, git would publish the refs with no
	// proposal at all.
	if setting.Cluster.Enabled {
		hookNames = append(hookNames, "reference-transaction")
		hookTpls = append(hookTpls,
			fmt.Sprintf(`#!/usr/bin/env %s
# AUTO GENERATED BY FORGEJO, DO NOT MODIFY
test "$1" = preparing && exit 0
data=$(cat)
cluster="$(dirname "$0")/reference-transaction.d/gitea"
if test "$1" = prepared && ! { test -f "${cluster}" && test -x "${cluster}" && test -s "${cluster}"; }; then
  echo "Forgejo: the cluster's reference-transaction hook is missing; nothing was written" >&2
  exit 1
fi
for hook in "$(dirname "$0")/reference-transaction.d"/*; do
  test -x "${hook}" && test -f "${hook}" || continue
  printf '%%s\n' "${data}" | "${hook}" "$1" || exit $?
done
`, setting.ScriptType))
		giteaHookTpls = append(giteaHookTpls,
			fmt.Sprintf(`#!/usr/bin/env %s
# AUTO GENERATED BY FORGEJO, DO NOT MODIFY
exec %s hook --config=%s reference-transaction "$1"
`, setting.ScriptType, util.ShellEscape(setting.AppPath), util.ShellEscape(setting.CustomConf)))
	}

	return hookNames, hookTpls, giteaHookTpls
}

func InitDelegateHooks(path string) (err error) {
	hookNames, hookTpls, giteaHookTpls := getHookTemplates()
	hookDir := filepath.Join(path, "hooks")

	for i, hookName := range hookNames {
		oldHookPath := filepath.Join(hookDir, hookName)
		newHookPath := filepath.Join(hookDir, hookName+".d", "gitea")

		if err := os.MkdirAll(filepath.Join(hookDir, hookName+".d"), os.ModePerm); err != nil {
			return fmt.Errorf("create hooks dir '%s': %w", filepath.Join(hookDir, hookName+".d"), err)
		}

		// WARNING: This will override all old server-side hooks
		if err = replaceHookFile(hookDir, oldHookPath, hookTpls[i]); err != nil {
			return err
		}
		if err = replaceHookFile(hookDir, newHookPath, giteaHookTpls[i]); err != nil {
			return err
		}
	}

	return nil
}

// replaceHookFile writes a hook in place without a moment where it is
// missing or partly written: a git process running the hook at that moment,
// the cluster's reference-transaction hook above all, would otherwise find
// none and go on as if it had passed. The content goes to a temporary file
// of tmpDir (the hooks directory, on the same file system, where git runs
// nothing by that name, never a .d directory, whose files the wrappers
// run), then replaces the hook by a rename. An identical executable hook is
// left as it is.
func replaceHookFile(tmpDir, hookPath, content string) error {
	if cur, err := os.ReadFile(hookPath); err == nil && string(cur) == content {
		if err := ensureExecutable(hookPath); err != nil {
			return fmt.Errorf("unable to set %s executable: %w", hookPath, err)
		}
		return nil
	}
	f, err := os.CreateTemp(tmpDir, "."+filepath.Base(hookPath)+".tmp-*")
	if err != nil {
		return fmt.Errorf("write hook file '%s': %w", hookPath, err)
	}
	tmp := f.Name()
	defer func() { _ = os.Remove(tmp) }()
	if _, err := f.WriteString(content); err != nil {
		f.Close()
		return fmt.Errorf("write hook file '%s': %w", hookPath, err)
	}
	if err := f.Sync(); err != nil {
		f.Close()
		return fmt.Errorf("write hook file '%s': %w", hookPath, err)
	}
	if err := f.Close(); err != nil {
		return fmt.Errorf("write hook file '%s': %w", hookPath, err)
	}
	if err := os.Chmod(tmp, 0o755); err != nil {
		return fmt.Errorf("unable to set %s executable: %w", hookPath, err)
	}
	if err := os.Rename(tmp, hookPath); err != nil {
		return fmt.Errorf("replace hook file '%s': %w", hookPath, err)
	}
	return nil
}

func ensureExecutable(filename string) error {
	fileInfo, err := os.Stat(filename)
	if err != nil {
		return err
	}
	if (fileInfo.Mode() & 0o100) > 0 {
		return nil
	}
	mode := fileInfo.Mode() | 0o100
	return os.Chmod(filename, mode)
}
